    if (!node) return false; // empty node

    if (set.has(k - node.val)) {
      return true; // found a pair that adds up to k
    } else {
      set.add(node.val); // add current node to set
      return traverse(node.left) || traverse(node.right); // recursively traverse left and right child nodes
